using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;using TutorialFramework;
[InitializeOnLoad]public static class WindPopupStyleTest{
 const string P="WindPopupStyleTest.";static readonly string[] ids={"Speed Curve Characteristics","Regulating DC Output from Wind Turbine using PWM Charger","Regulating DC Output from Wind Turbine using MPPT Charger","OFF Grid System Using Wind Turbine"};static bool Run{get=>SessionState.GetBool(P+"run",false);set=>SessionState.SetBool(P+"run",value);}static int Stage{get=>SessionState.GetInt(P+"stage",0);set=>SessionState.SetInt(P+"stage",value);}static int Index{get=>SessionState.GetInt(P+"index",0);set=>SessionState.SetInt(P+"index",value);}static double Due{get=>SessionState.GetFloat(P+"due",0);set=>SessionState.SetFloat(P+"due",(float)value);}const string report="Temp/WindPopupStyle/runtime.txt";
 static WindPopupStyleTest(){EditorApplication.update+=Tick;Application.logMessageReceived+=(m,s,t)=>{if(Run&&(t==LogType.Exception||t==LogType.Error||t==LogType.Assert)){File.AppendAllText(report,"ERROR "+m+"\n");SessionState.SetInt(P+"errors",SessionState.GetInt(P+"errors",0)+1);}};}
 static void Require(bool yes,string text){if(!yes)throw new Exception(text);}static Transform[] All()=>SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();static void Tick(){if(!Run&&File.Exists("Temp/wind-popup-test.flag")&&!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating){SessionState.SetBool(P+"preview",File.ReadAllText("Temp/wind-popup-test.flag").Trim()=="preview");File.Delete("Temp/wind-popup-test.flag");if(SceneManager.GetActiveScene().isDirty)return;File.WriteAllText(report,"");Run=true;Stage=Index=0;SessionState.SetInt(P+"errors",0);EditorSceneManager.OpenScene("Assets/_Project/Scenes/Main Menu.unity");Due=EditorApplication.timeSinceStartup+6;EditorApplication.EnterPlaymode();return;}if(!Run||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<Due)return;try{if(Stage==6){if(EditorApplication.isPlayingOrWillChangePlaymode)return;EditorSceneManager.OpenScene("Assets/_Project/Scenes/PV Lab.unity");Run=false;File.AppendAllText(report,"COMPLETE errors="+SessionState.GetInt(P+"errors",0)+"\n");return;}var manager=InteractionManager.Instance;if(!manager){Due=EditorApplication.timeSinceStartup+1;return;}
 if(Stage==0){manager.currentMode=ExperimentMode.Guided;var launch=Resources.FindObjectsOfTypeAll<MainMenuExperimentLauncher>().Single(l=>l.gameObject.scene==SceneManager.GetActiveScene()&&new SerializedObject(l).FindProperty("storyboardId").stringValue==ids[Index]);launch.GetComponent<Button>().onClick.Invoke();Stage=1;Due=EditorApplication.timeSinceStartup+7;return;}
 var all=All();var button=all.Single(t=>t.name=="Wind Speed Button");var trans=all.Single(t=>t.name=="Wire Transparency btn");var glow=button.Find("Step Highlight");var panel=all.Single(t=>t.name=="Wind Speed Panel").GetComponent<CanvasGroup>();var board=all.Select(t=>t.GetComponent<StoryboardSteps>()).Single(b=>b&&b.StoryboardID==ids[Index]);var speed=board.GetComponentsInChildren<WindTurbineSpeedController>(true).Single(w=>w.HasWindModel);var so=new SerializedObject(speed);int step=so.FindProperty("speedStepIndex").intValue;var slider=(Slider)so.FindProperty("speedSlider").objectReferenceValue;
 if(Stage==1){Require(button.parent==trans.parent&&button.GetSiblingIndex()==trans.GetSiblingIndex()+1,"Wrong hierarchy");Require(((RectTransform)button).anchoredPosition.y<((RectTransform)trans).anchoredPosition.y,"Button not below transparency");Require(button.GetComponent<Animator>().runtimeAnimatorController==trans.GetComponent<Animator>().runtimeAnimatorController,"Button animator style mismatch");Require(!glow.gameObject.activeSelf,"Highlight visible before step");Require(!slider.interactable,"Early slider unlock");board.GoToStep(step);Require(glow.gameObject.activeInHierarchy,"Speed step highlight missing");Require(!board.transform.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Slider Button pointer"&&t.gameObject.activeInHierarchy),"Old pointer still active");button.GetComponent<Button>().onClick.Invoke();Require(panel.alpha==1&&panel.blocksRaycasts,"Popup failed to open");Stage=2;Due=EditorApplication.timeSinceStartup+2;return;}
 if(Stage==2){if(Index==0)ScreenCapture.CaptureScreenshot("Temp/WindPopupStyle/guided-final.png");Stage=7;Due=EditorApplication.timeSinceStartup+1;return;}
 if(Stage==7){var checker=all.Select(t=>t.GetComponent<SliderRangeChecker>()).Single(c=>c&&new SerializedObject(c).FindProperty("slider").objectReferenceValue==slider);typeof(SliderRangeChecker).GetMethod("RefreshWindSlider",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(checker,null);Require(slider.interactable,"Speed step did not unlock slider");slider.value=1000;Stage=3;Due=EditorApplication.timeSinceStartup+1;return;}
 if(Stage==3){Require(board.CurrentStep!=step&&!glow.gameObject.activeSelf,"Highlight did not clear after max/step exit");Require(speed.CurrentSpeed==1000,"Slider math binding broken");panel.transform.GetComponentsInChildren<Button>(true).Single(b=>b.name=="Close").onClick.Invoke();Require(panel.alpha==0,"Close failed");board.GoToStep(step);Require(glow.gameObject.activeSelf,"Step re-entry highlight missing");board.GoToStep(0);Require(!glow.gameObject.activeSelf,"Highlight left visible after navigation");File.AppendAllText(report,"PASS EXP"+(Index+1)+" Guided: placement, shared visual style, step highlight/pointer replacement, unlock/max/exit/re-entry, popup.\n");manager.SetFree();Stage=4;Due=EditorApplication.timeSinceStartup+9;return;}
 if(Stage==4){Require(manager.Free&&!glow.gameObject.activeSelf,"Highlight leaked into Free Mode");button.GetComponent<Button>().onClick.Invoke();Require(panel.alpha==1,"Free Mode popup failed");panel.transform.GetComponentsInChildren<Button>(true).Single(b=>b.name=="Close").onClick.Invoke();Require(panel.alpha==0,"Free Mode close failed");File.AppendAllText(report,"PASS EXP"+(Index+1)+" Free: styled shared button/popup, no guided highlight.\n");Index++;if(Index==4||SessionState.GetBool(P+"preview",false)){Stage=6;EditorApplication.ExitPlaymode();Due=EditorApplication.timeSinceStartup+2;}else{manager.ReturnToExperimentMenu();Stage=0;Due=EditorApplication.timeSinceStartup+6;}}
 }catch(Exception e){File.AppendAllText(report,"FAIL "+e+"\n");SessionState.SetInt(P+"errors",SessionState.GetInt(P+"errors",0)+1);Stage=6;if(EditorApplication.isPlaying){EditorApplication.ExitPlaymode();Due=EditorApplication.timeSinceStartup+2;}else Run=false;}}
}
